if __name__ == "__main__":
    if len(sys.argv) < 2:
        sys.exit("uso: python predictor_v1_Grupo_12.py datos.csv [predicciones.csv]")
    data = pd.read_csv(sys.argv[1])
    pred = predictor_v1_Grupo_12(data)
    out = sys.argv[2] if len(sys.argv) > 2 else "predicciones_Grupo_12.csv"
    pd.DataFrame({"canceled_job_pred": pred}).to_csv(out, index=False)
    print(f"{len(pred)} predicciones guardadas en {out} (tasa de cancelación predicha: {pred.mean():.3f})")
